import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = (int) fs.nextLong();

        long[] positions = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) {
            positions[i] = total;
            total += fs.nextLong();
        }

        if ((total & 1L) != 0) {
            System.out.println("N");
            return;
        }

        HashSet<Long> trees = new HashSet<>(n * 2);
        for (long position : positions) {
            trees.add(position);
        }

        long half = total / 2;
        int pairs = 0;
        for (long position : positions) {
            long opposite = position < half ? position + half : position - half;
            if (position < opposite && trees.contains(opposite)) {
                pairs++;
                if (pairs >= 2) {
                    System.out.println("S");
                    return;
                }
            }
        }

        System.out.println("N");
    }
}
